use xiom.io;

type Date = {
  day: Int;
  month: Int;
  year: Int;
}

enum EventType {
  Meeting,
  Birthday,
  Holiday(name: Str),
  Deadline,
}

type Event = {
  date: Date;
  kind: EventType;
}

fn format(e: Event) -> Str {
  let date_str = e.date.day + "/" + e.date.month + "/" + e.date.year;
  match e.kind {
    Meeting => { return "Meeting on " + date_str; }
    Birthday => { return "Birthday on " + date_str; }
    Holiday(name) => { return name + " on " + date_str; }
    Deadline => { return "Deadline on " + date_str; }
  }
}

fn in_year(e: Event, yr: Int) -> Bool {
  return e.date.year == yr;
}

fn main() -> Int {
  let bday = Event{
    date: Date{ day: 10; month: 3; year: 2026; };
    kind: EventType.Birthday;
  };
  let holiday = Event{
    date: Date{ day: 1; month: 1; year: 2026; };
    kind: EventType.Holiday("New Year");
  };
  var count = 0;
  if in_year(bday, 2026) { count = count + 1; }
  if in_year(holiday, 2026) { count = count + 1; }
  return count;
}
